<?php

declare(strict_types=1);
require_once __DIR__.'/CompanyFinancialJournal.php';require_once __DIR__.'/CompanyReports.php';

/** Journal of verified local mutations; observations never masquerade as original history. */
final class CompanyLedgerReports
{
    public function __construct(private $db,private string $p,private $guard=null){if(!preg_match('/^[A-Za-z0-9_]+$/D',$p))throw new InvalidArgumentException('Invalid table prefix');}
    private function rows(string $sql,array $args=[]):array{return IssuerStorage::query($this->db,$sql,$args)->result_array();}
    private function authorize(int $issuer,int $actor):void{$acl=new IssuerResourceAccess($this->db,$this->p);foreach(CompanyReports::CAPABILITIES as [$feature,$cap])if(!$acl->can($issuer,$actor,$feature,$cap))throw new DomainException('company_ledger_access_denied');}
    private function tables():array{$tables=['issuers_lock','issuers_registry','issuers_staff','issuers_resource_permissions','issuers_installation_identity','staff','issuers_audit','company_financial_events'];foreach(['invoices','issuers_invoice_documents','creditnotes','company_credit_documents','company_expenses','invoicepaymentrecords','company_payment_receipts','company_credit_entries','company_bank_receipt_components'] as $table)if($this->db->table_exists($this->p.$table))$tables[]=$table;return $tables;}
    private function transaction(int $issuer,int $actor,callable $work){$this->authorize($issuer,$actor);CompanyFinancialJournalSchema::assertValid($this->db,$this->p);return IssuerTransaction::run($this->db,$this->p,$this->tables(),function()use($issuer,$actor,$work){(new IssuerResourceAccess($this->db,$this->p))->lockFinancialIdentity($issuer,$actor);$this->authorize($issuer,$actor);if($this->guard!==null)($this->guard)();$result=$work();$this->authorize($issuer,$actor);if($this->guard!==null)($this->guard)();return $result;});}
    private static function date(string $value):string{$date=DateTimeImmutable::createFromFormat('!Y-m-d',$value);if(!$date||$date->format('Y-m-d')!==$value)throw new DomainException('company_ledger_invalid_filter');return $value;}
    private static function cutoff(?string $value):string{$value=$value===null?gmdate('Y-m-d H:i:s'):str_replace('T',' ',$value);$date=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$value,new DateTimeZone('UTC'));if(!$date||$date->format('Y-m-d H:i:s')!==$value||$value>gmdate('Y-m-d H:i:s'))throw new DomainException('company_ledger_invalid_filter');return $value;}
    private static function idOrZero($value):int{if($value===0||$value==='0')return 0;return IssuerPolicy::id($value);}
    private static function add(int &$sum,int $amount):void{if(($amount>0&&$sum>PHP_INT_MAX-$amount)||($amount<0&&$sum<PHP_INT_MIN-$amount))throw new DomainException('company_ledger_invalid_event');$sum+=$amount;}
    private static function money($amount):int{try{return CompanyInvoiceAmounts::minor((string)$amount);}catch(Throwable $e){throw new DomainException('company_ledger_invalid_event');}}
    private function coverage(int $issuer,int $watermark,string $through):array
    {
        $counts=['invoice'=>0,'credit'=>0,'expense'=>0,'payment'=>0,'payment_reversal'=>0,'bank_components'=>0,'credit_entry'=>0];$available=[];$queries=[
            'invoice'=>['invoices','issuers_invoice_documents','SELECT COUNT(*) n FROM '.$this->p.'invoices WHERE issuer_id=?'],
            'credit'=>['creditnotes','company_credit_documents','SELECT COUNT(*) n FROM '.$this->p.'creditnotes WHERE issuer_id=?'],
            'expense'=>['company_expenses','company_expenses','SELECT COUNT(*) n FROM '.$this->p.'company_expenses WHERE issuer_id=?'],
            'payment'=>['invoicepaymentrecords','company_payment_receipts','SELECT COUNT(*) n FROM '.$this->p.'invoicepaymentrecords p JOIN '.$this->p.'invoices i ON i.id=p.invoiceid WHERE i.issuer_id=?'],
            'payment_reversal'=>['company_credit_entries','company_credit_entries',"SELECT COUNT(*) n FROM {$this->p}company_credit_entries WHERE issuer_id=? AND kind='manual_reverse'"],
            'bank_components'=>['company_bank_receipt_components','company_bank_receipt_components','SELECT COUNT(*) n FROM '.$this->p.'company_bank_receipt_components WHERE issuer_id=?'],
            'credit_entry'=>['company_credit_entries','company_credit_entries',"SELECT COUNT(*) n FROM {$this->p}company_credit_entries WHERE issuer_id=? AND kind IN ('apply','unapply','refund','refund_reverse')"],
        ];foreach($queries as $type=>[$table,$needs,$sql]){$available[$type]=$this->db->table_exists($this->p.$table)&&$this->db->table_exists($this->p.$needs);if($available[$type])$counts[$type]=(int)$this->rows($sql,[$issuer])[0]['n'];}
        $originals=array_fill_keys(array_keys($counts),0);$observed=array_fill_keys(array_keys($counts),0);foreach($this->rows('SELECT source_type,kind,COUNT(DISTINCT source_id) n,COUNT(*) event_count FROM '.$this->p.'company_financial_events WHERE issuer_id=? AND issuer_sequence<=? AND recorded_at<=? GROUP BY source_type,kind',[$issuer,$watermark,$through]) as $row){if($row['kind']==='bank_components_recorded'){$originals['bank_components']+=(int)$row['event_count'];continue;}if($row['kind']==='receipt_reversed'){$originals['payment_reversal']+=(int)$row['event_count'];continue;}if(str_starts_with($row['kind'],'observed_'))$observed[$row['source_type']]+=(int)$row['n'];elseif(in_array($row['kind'],['invoice_issued','credit_issued','expense_recorded','receipt_recorded','credit_applied','credit_unapplied','credit_refunded','credit_refund_reversed'],true))$originals[$row['source_type']]+=(int)$row['n'];}
        $unrecorded=[];foreach($counts as $type=>$count)$unrecorded[$type]=max(0,$count-$originals[$type]-$observed[$type]);return ['scope'=>'all_current_owned_sources_at_query','available_domains'=>$available,'owned_sources'=>$counts,'captured_originals'=>$originals,'observed_not_original'=>$observed,'without_original_evidence'=>$unrecorded,'complete_original_history'=>!in_array(false,$available,true)&&array_sum($observed)===0&&array_sum($unrecorded)===0];
    }
    private static function legs(array $event):array
    {
        if($event['basis']===CompanyFinancialJournal::BASELINE)return [];$amount=self::money($event['amount']);$date=$event['book_date'];$legs=[];$put=static function(string $metric,int $value,string $day)use(&$legs):void{$legs[]=['metric'=>$metric,'amount'=>$value,'date'=>$day];};
        switch($event['kind']){
            case 'invoice_issued':$put('invoice_nominal',$amount,$date);$put('invoice_after_changes',$amount,$date);break;
            case 'expense_recorded':$put('expense_nominal',$amount,$date);$put('expense_after_changes',$amount,$date);break;
            case 'invoice_updated':case 'expense_updated':$old=self::money($event['before']['total']??null);$new=self::money($event['after']['total']??null);$oldDate=self::date($event['before']['date']??'');$newDate=self::date($event['after']['date']??'');if($new!==$amount||$newDate!==$date||$oldDate!==$event['previous_book_date'])throw new DomainException('company_ledger_invalid_event');$metric=$event['kind']==='invoice_updated'?'invoice_after_changes':'expense_after_changes';$put($metric,-$old,$oldDate);$put($metric,$new,$newDate);break;
            case 'invoice_cancelled':$put('invoice_after_changes',-$amount,$date);break;
            case 'expense_cancelled':$put('expense_after_changes',-$amount,$date);break;
            case 'receipt_recorded':$put('receipt_nominal',$amount,$date);$put('receipt_after_reversals',$amount,$date);break;
            case 'receipt_reversed':$put('receipt_reversals',$amount,$date);$put('receipt_after_reversals',-$amount,$date);break;
            case 'bank_components_recorded':
                $data=$event['after'];$cash=self::money($data['cash_principal']??null);$discount=self::money($data['discount']??null);$abatement=self::money($data['abatement']??null);$charges=self::money($data['charges_aggregate']??null);$paid=self::money($data['paid']??null);if($cash+$discount+$abatement!==$amount||$cash+$charges!==$paid)throw new DomainException('company_ledger_invalid_event');$put('bank_settlement_discount',$discount,$date);$put('bank_settlement_abatement',$abatement,$date);$put('bank_noncash_reductions',$discount+$abatement,$date);$put('bank_charges_aggregate_observed',$charges,$date);$put('bank_paid_observed',$paid,$date);if(($data['net_observed']??null)!==null)$put('bank_net_observed',self::money($data['net_observed']),$date);break;
            case 'credit_issued':$put('credit_nominal',$amount,$date);$put('credit_after_cancellations',$amount,$date);break;
            case 'credit_cancelled':$put('credit_after_cancellations',-$amount,$date);break;
            case 'credit_applied':$put('credit_applied_nominal',$amount,$date);$put('credit_applied_after_reversals',$amount,$date);break;
            case 'credit_unapplied':$put('credit_applied_after_reversals',-$amount,$date);break;
            case 'credit_refunded':$put('refund_nominal',$amount,$date);$put('refund_after_reversals',$amount,$date);break;
            case 'credit_refund_reversed':$put('refund_after_reversals',-$amount,$date);break;
            default:throw new DomainException('company_ledger_invalid_event');
        }return $legs;
    }
    private function build(int $issuer,string $from,string $to,string $through,$watermark,$after):array
    {
        self::date($from);self::date($to);if($from>$to||(new DateTimeImmutable($from))->diff(new DateTimeImmutable($to))->days>366)throw new DomainException('company_ledger_invalid_filter');$max=(int)$this->rows('SELECT COALESCE(MAX(issuer_sequence),0) n FROM '.$this->p.'company_financial_events WHERE issuer_id=?',[$issuer])[0]['n'];$watermark=$watermark===null?$max:self::idOrZero($watermark);$after=self::idOrZero($after);if($watermark>$max||$after>$watermark)throw new DomainException('company_ledger_invalid_filter');
        $rows=$this->rows('SELECT * FROM '.$this->p.'company_financial_events WHERE issuer_id=? AND issuer_sequence<=? AND recorded_at<=? AND (book_date BETWEEN ? AND ? OR previous_book_date BETWEEN ? AND ?) ORDER BY issuer_sequence LIMIT 10001',[$issuer,$watermark,$through,$from,$to,$from,$to]);if(count($rows)>10000)throw new DomainException('company_ledger_period_limit');$journal=new CompanyFinancialJournal($this->db,$this->p);$events=[];$totals=[];$observations=0;
        foreach($rows as $row){$event=$journal->decode($row);$event['issuer_sequence']=(int)$event['issuer_sequence'];$event['legs']=[];if($event['basis']===CompanyFinancialJournal::BASELINE)$observations++;foreach(self::legs($event) as $leg){if($leg['date']<$from||$leg['date']>$to)continue;$currency=$event['currency'];if(!isset($totals[$currency]))$totals[$currency]=[];if(!isset($totals[$currency][$leg['metric']]))$totals[$currency][$leg['metric']]=0;self::add($totals[$currency][$leg['metric']],$leg['amount']);$event['legs'][]=$leg+['decimal'=>CompanyInvoiceAmounts::decimal($leg['amount'])];}if($event['issuer_sequence']>$after)$events[]=$event;}
        $more=count($events)>100;$page=array_slice($events,0,100);$next=$more?$page[count($page)-1]['issuer_sequence']:null;ksort($totals);foreach($totals as &$metrics)foreach($metrics as &$amount)$amount=CompanyInvoiceAmounts::decimal($amount);unset($metrics,$amount);return ['issuer_id'=>$issuer,'from'=>$from,'to'=>$to,'recorded_through_utc'=>$through,'watermark'=>$watermark,'after'=>$after,'next'=>$next,'events'=>$page,'matched_events'=>count($rows),'observations_in_period'=>$observations,'currencies'=>$totals,'coverage'=>$this->coverage($issuer,$watermark,$through),'basis'=>'verified_local_events_not_bank_cashflow_or_fiscal_gl'];
    }
    public function report($issuer,$actor,string $from,string $to,?string $through=null,$watermark=null,$after=0):array{$issuer=IssuerPolicy::id($issuer);$actor=IssuerPolicy::id($actor);$through=self::cutoff($through);return $this->transaction($issuer,$actor,fn():array=>$this->build($issuer,$from,$to,$through,$watermark,$after));}
    public function csv($issuer,$actor,string $from,string $to,?string $through=null,$watermark=null,$after=0):array
    {
        $issuer=IssuerPolicy::id($issuer);$actor=IssuerPolicy::id($actor);$through=self::cutoff($through);return $this->transaction($issuer,$actor,function()use($issuer,$actor,$from,$to,$through,$watermark,$after):array{$report=$this->build($issuer,$from,$to,$through,$watermark,$after);$stream=fopen('php://temp','w+');if(!$stream)throw new RuntimeException('issuer_ledger_export_failed');try{fwrite($stream,"\xEF\xBB\xBF");fputcsv($stream,['issuer_id','issuer_sequence','kind','source_type','source_id','book_date','previous_book_date','recorded_at_utc','currency','currency_basis','magnitude','event_basis','before_total','after_total','evidence_key','payload_hash','record_hash'],';','"','');foreach($report['events'] as $event)fputcsv($stream,array_map(static function($value){$value=(string)$value;return preg_match('/^[\x00-\x20]*[=+\-@]/',$value)?"'".$value:$value;},[$issuer,$event['issuer_sequence'],$event['kind'],$event['source_type'],$event['source_id'],$event['book_date'],$event['previous_book_date'],$event['recorded_at'],$event['currency'],$event['currency_basis'],$event['amount'],$event['basis'],$event['before']['total']??'',$event['after']['total']??'',$event['evidence_key'],$event['payload_hash'],$event['record_hash']]),';','"','');rewind($stream);$csv=stream_get_contents($stream);if(!is_string($csv))throw new RuntimeException('issuer_ledger_export_failed');}finally{fclose($stream);}$meta=json_encode(['from'=>$from,'to'=>$to,'recorded_through_utc'=>$through,'watermark'=>$report['watermark'],'after'=>$report['after'],'next'=>$report['next'],'sha256'=>hash('sha256',$csv)],JSON_THROW_ON_ERROR);IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'issuers_audit(actor_id,event,issuer_id,subject_id,created_at,metadata_json) VALUES(?,?,?,?,?,?)',[$actor,'company_financial_journal_exported',$issuer,$issuer,date('Y-m-d H:i:s'),$meta]);$id=(int)$this->db->insert_id();if(!$this->rows('SELECT id FROM '.$this->p.'issuers_audit WHERE id=? AND issuer_id=? AND metadata_json=?',[$id,$issuer,$meta]))throw new RuntimeException('issuer_ledger_export_failed');return ['csv'=>$csv,'next'=>$report['next'],'watermark'=>$report['watermark'],'recorded_through_utc'=>$through];});
    }
}
